/* eslint-disable no-restricted-syntax -- third-party brand colour, see below */
// ── Brand marks ───────────────────────────────────────────────────────
//
// The two-colour brand artwork, inline. Same reasoning as icons.tsx, which
// replaced 13 hand-written <img> tags: art referenced by URL is art the
// component cannot carry with it. These marks lived at
// /conferences/2026/assets/logos/*.svg, which resolves on this site and nowhere
// else — so the moment a component was lifted out of the app (a preview, an
// export, a design tool) the mark vanished and left a broken-image box behind.
//
// Unlike icons.tsx these do NOT paint with currentColor: they are brand
// artwork with fixed colours, and the social marks come as a resting grey and a
// full-colour pair that cross-fade on hover.
//
// ⛔ The file-level eslint-disable is for the hex literals in Instagram's
//    gradient, LinkedIn blue and the badge's own palette. Those are OTHER
//    organisations' brand colours: they must NOT track the UXHI palette, which
//    is exactly what the rule would otherwise make them do. The three values
//    that ARE ours — gray-110 on the resting glyphs, purple-140 and yellow-80
//    in the shaka — are emitted as var() and do track it.
//
// Generated from the SVG sources, which stay in public/ for OG images and any
// non-React use. Figma's duplicate display-p3 declarations are dropped: they
// restate the sRGB value already on the fill attribute.

interface MarkProps {
  /** Rendered size in px. Omit to let CSS size it. */
  size?: number | string;
  className?: string;
  style?: React.CSSProperties;
}

